			/**
			 * 선택 자원별 예약 시간 필터링
			 */
			function filterResrceRsvtAltmntPrecon() {
			    
			    var resrceClMngList = app.lookup("dsResrceClMngList");
			    var rsvtPreconList = app.lookup("dsRsvtPreconList");
			    var rsvtAltmntPreconList = app.lookup("dsRsvtAltmntPreconList");
			    
			    var resrceClMngEsntalNo = "";
			    var startDate = "";
			    var startTime = "";
			    var endDate = "";
			    var endTime = "";
			    
			    var rsvtSn = "";
			    //    var rsvtSnBf = "";
			    //    var rsvtSnAf = "";
			    
			    voColNameArray = [];
			    voColNameArray = rsvtAltmntPreconList.getColumnNames();
			    
			    for (var i = 0; i < rsvtPreconList.getRowCount(); i++) {
			        
			        for (var j = 0; j < rsvtAltmntPreconList.getRowCount(); j++) {
			            
			            if (rsvtPreconList.getValue(i, "RESRCE_CL_MNG_ESNTAL_NO").toString() == rsvtAltmntPreconList.getValue(j, "RESRCE_CL_MNG_ESNTAL_NO").toString()) {
			                
			                resrceClMngEsntalNo = rsvtPreconList.getValue(i, "RESRCE_CL_MNG_ESNTAL_NO");
			                startDate = rsvtPreconList.getValue(i, "RSVT_BGNG_YMD");
			                startTime = rsvtPreconList.getValue(i, "RSVT_BGNG_HR");
			                endDate = rsvtPreconList.getValue(i, "RSVT_END_YMD");
			                endTime = rsvtPreconList.getValue(i, "RSVT_END_HR");
			                
			//                console.log("startDate ::::::::::::" + Number(startDate));
			//                console.log("endDate ::::::::::::" + Number(endDate));
			                
			                rsvtSn = rsvtPreconList.getValue(i, "RSVT_SN");
			                //                rsvtSnBf = rsvtPreconList.getValue(i-1, "RSVT_SN");
			                //                rsvtSnAf = rsvtPreconList.getValue(i+1, "RSVT_SN");
			                //                console.log("rsvtSn ::::::::::::" + rsvtSn);
			                //                console.log("rsvtSnBf ::::::::::::" + rsvtSnBf);
			                //                console.log("rsvtSnAf ::::::::::::" + rsvtSnAf);
			                
			                if (Number(startDate) == Number(endDate)) {
			                    // 시작일과 종료일이 같은 단일 예약인 경우 마커 표시
			                    replaceRsvtAltmntPreconDataSet(resrceClMngEsntalNo, startDate, startTime, endDate, endTime, rsvtSn);
			                    
			                } else if (Number(startDate) <= Number(endDate)) {
			                    // 시작일과 종료일이 같지 않고 종료일이 더큰 다일 예약인 경우 마커 표시
			                    
			                    if (Number(startDate) == Number(searchDate)) {
			                        // 시작일과 선택일 이 같은 케이스
			                        
			                        // 화면상 최대 마커 표시가 20:50 이므로 강제로 화면상 풀타임 셋팅
			                        endTime = "2050";
			                        
			                        //replaceRsvtAltmntPreconDataSet01(resrceClMngEsntalNo, startDate, startTime, endDate, endTime);
			                        
			                    } else if (Number(startDate) < Number(searchDate) && Number(endDate) > Number(searchDate)) {
			                        // 선택일자가 시작일보다 크고 종료일보다 작은 경우
			                        
			                        // 화면상 최소 마커 표시가 07:00 이므로 강제로 화면상 풀타임 셋팅
			                        startTime = "0700";
			                        
			                        // 화면상 최대 마커 표시가 20:50 이므로 강제로 화면상 풀타임 셋팅
			                        endTime = "2050";
			                        
			                        //replaceRsvtAltmntPreconDataSet02(resrceClMngEsntalNo, startDate, startTime, endDate, endTime);
			                        
			                    } else if (Number(endDate) == Number(searchDate)) {
			                        // 선택일이 종료일과 같은 경우
			                        // 화면상 최소 마커 표시가 07:00 이므로 강제로 화면상 풀타임 셋팅
			                        startTime = "0700";
			                        //replaceRsvtAltmntPreconDataSet03(resrceClMngEsntalNo, startDate, startTime, endDate, endTime);
			                        
			                    }
			                    replaceRsvtAltmntPreconDataSet(resrceClMngEsntalNo, startDate, startTime, endDate, endTime, rsvtSn);
			                }
			            }
			        }
			    }
			}

			/**
			 * 시간별 예약현황 마크 활성 데이터 가공 > 시작일과 종요일이 같은 단일 예약 마커 표시
			 * resrceClMngEsntalNo : 자원분류관리고유번호
			 * rsvtSn : 예약일련번호
			 */
			function replaceRsvtAltmntPreconDataSet(resrceClMngEsntalNo, startDate, startTime, endDate, endTime, rsvtSn) {
			    
			    var rsvtAltmntPreconList = app.lookup("dsRsvtAltmntPreconList");
			    for (var i = 0; i < voColNameArray.length; i++) {
			        
			        for (var j = 0; j < rsvtAltmntPreconList.getRowCount(); j++) {
			            
			            //            console.log("RESRCE_CL_MNG_ESNTAL_NO ::::::::::" + rsvtAltmntPreconList.getValue(j, "RESRCE_CL_MNG_ESNTAL_NO").toString());
			            //            console.log("resrceClMngEsntalNo ::::::::::" + resrceClMngEsntalNo);
			            //console.log("RSVT_SN ::::::::::" + rsvtAltmntPreconList.getValue(j, "RSVT_SN").toString());
			            //console.log("rsvtSn ::::::::::" + rsvtSn);
			            
			            // 2022.11.04 이태호_RSVT_SN 조건 추가
			            //            if(rsvtAltmntPreconList.getValue(j, "RESRCE_CL_MNG_ESNTAL_NO").toString() == resrceClMngEsntalNo){
			            if (rsvtAltmntPreconList.getValue(j, "RESRCE_CL_MNG_ESNTAL_NO").toString() == resrceClMngEsntalNo &&
			                rsvtAltmntPreconList.getValue(j, "RSVT_SN").toString() == rsvtSn) {
			                
			                if (voColNameArray[i].toString() != "RESRCE_CL_MNG_ESNTAL_NO" && voColNameArray[i].toString() != "RESRCE_NM") {
			                    if (Number(voColNameArray[i].toString().substring(1, 5)) >= startTime && Number(voColNameArray[i].toString().substring(1, 5)) < endTime) {
			                        
			                        var chkStr = rsvtAltmntPreconList.getRow(j).getValue(voColNameArray[i]);
			                        
			                        rsvtAltmntPreconList.getRow(j).setValue(voColNameArray[i].toString(), "Y");
			                        
			                        if (chkStr.toString().substring(0, 1) == "S") {
			                            
			                        } else if (chkStr.toString().substring(0, 1) == "E") {
			                            
			                            var eEndTimeHourCheckValue = Number(chkStr.toString().substring(1, 3));
			                            var eEndTimeMinCheckValue = Number(chkStr.toString().substring(3, 5));
			                            
			                            var eEndTimeCheckValue = Number(chkStr.toString().substring(1, 5));
			                            
			                            var originEndTimeColumnName = "C" + chkStr.toString().substring(1, 5);
			                            var replaceEndTimeColumnName = "C" + eEndTimeCheckValue.toString();
			                            
			//                            console.log("startDate = " + startDate);
			//                            console.log("endDate = " + endDate);
			                            
			                            if (startDate == endDate) {
			                                
			                                if (eEndTimeMinCheckValue == 0) {
			                                    replaceEndTimeColumnName = eEndTimeCheckValue - 50;
			                                } else {
			                                    replaceEndTimeColumnName = eEndTimeCheckValue - 10;
			                                } // end if
			                            }
			                            
			//                            console.log("eEndTimeMinCheckValue : " + eEndTimeMinCheckValue);
			//                            console.log("orign Endtime : " + originEndTimeColumnName);
			//                            console.log("replace Endtime : " + replaceEndTimeColumnName);
			                            
			                            if (voColNameArray[i] == originEndTimeColumnName) {
			                                
			//                                console.log("if orign Endtime : " + originEndTimeColumnName);
			                                rsvtAltmntPreconList.getRow(j).setValue(originEndTimeColumnName, originEndTimeColumnName);
			                            } // end if
			                            
			                            if (voColNameArray[i] == replaceEndTimeColumnName) {
			//                                console.log("if replace Endtime : " + replaceEndTimeColumnName);
			                                rsvtAltmntPreconList.getRow(j).setValue(replaceEndTimeColumnName, "Y");
			                            } // end if
			                            
			                        } // end if
			                        
			                    } // end if
			                    
			                } // end if
			                
			            } // end if
			            
			        } // end for
			        
			    } // end for
			    
			    app.lookup("dsRsvtAltmntPreconList").commit();
			    
			}

